import{_ as t}from"./chunks/teek.HR1JaYzY.js";import{o as e,c as d,aj as o}from"./chunks/vue-vendor.D7waMIYK.js";const b=JSON.parse('{"title":"插件系统概览","description":"","frontmatter":{},"headers":[],"relativePath":"overview.md","filePath":"overview.md","lastUpdated":null}'),s={name:"overview.md"};function n(l,a,i,c,r,p){return e(),d("div",null,[...a[0]||(a[0]=[o(`<h1 id="插件系统概览" tabindex="-1">插件系统概览 <a class="header-anchor" href="#插件系统概览" aria-label="Permalink to &quot;插件系统概览&quot;">​</a></h1><p>插件是带 <code>plugin.json</code> 的 Java 目录或 jar。可添加页面、按钮、命令、弹窗、事件，也可直接操作 JavaFX 场景树。</p><h2 id="能力" tabindex="-1">能力 <a class="header-anchor" href="#能力" aria-label="Permalink to &quot;能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>入口</th><th>位置</th></tr></thead><tbody><tr><td>完整页面</td><td><code>ctx.ui().page(...)</code></td><td>「更多」左栏</td></tr><tr><td>标题栏按钮</td><td><code>ctx.ui().titleButton(...)</code></td><td>窗口右上角</td></tr><tr><td>首页按钮</td><td><code>ctx.ui().launchButton(...)</code></td><td>首页「插件扩展」</td></tr><tr><td>工具按钮</td><td><code>ctx.ui().toolButton(...)</code></td><td>「更多 → 实用工具」</td></tr><tr><td>悬浮按钮</td><td><code>ctx.ui().floatButton(...)</code></td><td>右下角</td></tr><tr><td>命令</td><td><code>ctx.commands().register(...)</code></td><td>搜索、详情、插件按钮</td></tr><tr><td>弹窗</td><td><code>ctx.dialogs()</code></td><td>消息、确认、输入、自定义节点</td></tr><tr><td>事件</td><td><code>ctx.events().on(...)</code></td><td>启动、切页、开游戏、安装</td></tr><tr><td>任意布局</td><td><code>ctx.stage()</code></td><td>直接改 <code>Stage</code> / <code>Scene</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">安全边界</p><p>插件拥有完整权限；启动器只隔离类加载器，不限制行为。只安装可信插件。</p></div><h2 id="插件目录" tabindex="-1">插件目录 <a class="header-anchor" href="#插件目录" aria-label="Permalink to &quot;插件目录&quot;">​</a></h2><p>插件位于 <code>.tcl/plugins/</code>，支持两种形态。</p><h3 id="目录插件" tabindex="-1">目录插件 <a class="header-anchor" href="#目录插件" aria-label="Permalink to &quot;目录插件&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.tcl/plugins/demo.hello/</span></span>
<span class="line"><span>├── plugin.json          # 必需</span></span>
<span class="line"><span>├── hello.jar            # 至少一个 jar</span></span>
<span class="line"><span>├── lib/                 # 可选依赖</span></span>
<span class="line"><span>│   └── some-lib.jar</span></span>
<span class="line"><span>├── icon.png             # 可选列表图标</span></span>
<span class="line"><span>└── thumbnail.png        # 可选详情封面</span></span></code></pre></div><h3 id="单-jar-插件" tabindex="-1">单 jar 插件 <a class="header-anchor" href="#单-jar-插件" aria-label="Permalink to &quot;单 jar 插件&quot;">​</a></h3><p>清单放在 jar 根目录，导入时展开成目录：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>demo-hello.jar</span></span>
<span class="line"><span>├── plugin.json</span></span>
<span class="line"><span>└── demo/HelloPlugin.class</span></span></code></pre></div><p>入口在「更多 → 插件」：刷新、导入、启停、详情、命令、打开目录、删除。</p><h2 id="加载流程" tabindex="-1">加载流程 <a class="header-anchor" href="#加载流程" aria-label="Permalink to &quot;加载流程&quot;">​</a></h2><ol><li>启动约 1.2 秒后扫描 <code>.tcl/plugins/</code>，按目录名排序。</li><li>读取 <code>plugin.json</code>，校验 <code>id</code>、<code>main</code>、API 版本。</li><li>创建独立 <code>URLClassLoader</code>，父加载器为启动器。</li><li>实例化 <code>main</code> 类并调用 <code>onLoad(ctx)</code>。</li><li>手动启用时再调用 <code>onEnable()</code>。</li><li>禁用或卸载时调用 <code>onDisable()</code>，关闭类加载器并移除页面、按钮、命令。</li></ol><div class="tip custom-block"><p class="custom-block-title">线程模型</p><p>回调和事件都在 JavaFX 线程执行。耗时任务放后台线程，再用 <code>Platform.runLater</code> 回到 UI。</p></div><h2 id="确认加载" tabindex="-1">确认加载 <a class="header-anchor" href="#确认加载" aria-label="Permalink to &quot;确认加载&quot;">​</a></h2><p>日志 <code>.tcl/log/launcher.log</code> 出现下面一行，即加载成功：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[09:19:51] [插件][demo.hello] 已加载 Hello 插件 1.0.0</span></span></code></pre></div><p>「更多」左栏出现插件页面，「更多 → 插件」显示「已启用」。失败会显示异常。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/TCraft-Launcher/wiki/guide">第一个插件</a></li><li><a href="/TCraft-Launcher/wiki/manifest">plugin.json</a></li><li><a href="/TCraft-Launcher/wiki/references">进阶参考</a></li></ul>`,22)])])}const m=t(s,[["render",n]]);export{b as __pageData,m as default};
